mkdir -p /tmp/bl069 && cat > /tmp/bl069/scan.py <<'EOF'
import ast, pathlib, sys
root = pathlib.Path(sys.argv[1])
out = []
for path in sorted(list((root/"src").rglob("*.py")) + list((root/"tests").rglob("*.py")) + list((root/"scripts").rglob("*.py"))):
    rel = path.relative_to(root)
    if "migrations" in rel.parts or "web_dist" in rel.parts:
        continue
    tree = ast.parse(path.read_text(encoding="utf-8"))
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) and node.module and node.module.startswith("sensei_top"):
            for a in node.names:
                if a.name.startswith("_") and a.name != "_":
                    out.append(f"{rel} IMPORT {node.module}.{a.name} L{node.lineno}")
        if isinstance(node, ast.ImportFrom) and node.level and node.module is None or (isinstance(node, ast.ImportFrom) and node.level):
            for a in node.names:
                if a.name.startswith("_") and a.name != "_":
                    out.append(f"{rel} RELIMPORT .{node.module}.{a.name} L{node.lineno}")
        if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name) and node.value.id in ("classify",):
            out.append(f"{rel} ATTR classify.{node.attr} L{node.lineno}")
print("\n".join(out))
EOF
cd ~/.cache/sensei-top-wt/bench-bl-069-sonnet && uv run python -I /tmp/bl069/scan.py "$PWD"
